import {readFile,readdir,rm} from 'node:fs/promises';
import {join} from 'node:path';
const root='/Users/itayzrihan/Library/Application Support/OpenCut Local';
const keep=new Set();
for(const name of ['current.json','previous.json','candidate.json']){try{keep.add(JSON.parse(await readFile(join(root,name),'utf8')).id);}catch{}}
const releases=join(root,'releases');
const removed=[];
for(const name of await readdir(releases)){
 if(!/^2026-10-20T19-\d\d-\d\d-\d{3}Z-70d8e8b4$/.test(name)||keep.has(name))continue;
 await rm(join(releases,name),{recursive:true}); removed.push(name);
}
console.log(JSON.stringify({removedGeneratedReleases:removed,retained:[...keep]}));
